  1→/* The demo switch bar: three ways between the start page, the party pages and the
  2→   operator console. It scrolls away with the page — never pinned — because a sticky
  3→   bar would push the filing form's buttons off a phone screen. It wraps instead of
  4→   shrinking, so every link keeps a full-size tap target. */
  5→
  6→.switch-bar {
  7→  display: flex;
  8→  flex-wrap: wrap;
  9→  align-items: center;
 10→  gap: 0.5rem;
 11→  padding: 0.6rem 1.25rem;
 12→  background: #ffffff;
 13→  border-bottom: 1px solid #E5E0DC;
 14→  font-family: Poppins, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
 15→  font-size: 0.9rem;
 16→}
 17→
 18→.switch-bar a {
 19→  display: inline-block;
 20→  padding: 0.55rem 1rem;
 21→  color: #31373E;
 22→  text-decoration: none;
 23→  border: 1px solid transparent;
 24→  border-radius: 9999px;
 25→}
 26→
 27→.switch-bar a:hover {
 28→  border-color: #E93864;
 29→}
 30→
 31→.switch-bar a:focus-visible {
 32→  outline: 3px solid #E93864;
 33→  outline-offset: 2px;
 34→}
 35→
 36→.switch-bar a[aria-current] {
 37→  color: #ffffff;
 38→  background: #CC2852;
 39→  font-weight: 600;
 40→}
 41→
 42→@media (max-width: 420px) {
 43→  .switch-bar {
 44→    gap: 0.35rem;
 45→    padding: 0.5rem 0.75rem;
 46→  }
 47→
 48→  .switch-bar a {
 49→    padding: 0.45rem 0.6rem;
 50→  }
 51→}
 52→
 53→/* The filing form is a one-screen frame (party.css). With the bar above it, the
 54→   body becomes that screen: a column the bar sits at the top of, and the frame
 55→   takes what is left, so the fine print and the actions stay on screen. */
 56→body:has(.filing-shell #form-steps:not([hidden])) {
 57→  display: flex;
 58→  flex-direction: column;
 59→  height: 100vh;
 60→  height: 100dvh;
 61→}
 62→
 63→body:has(.filing-shell #form-steps:not([hidden])) > .switch-bar {
 64→  flex: none;
 65→}
 66→
 67→body:has(.filing-shell #form-steps:not([hidden])) > .filing-shell {
 68→  flex: 1 1 auto;
 69→  min-height: 0;
 70→  height: auto;
 71→  width: 100%;
 72→  box-sizing: border-box;
 73→}
 74→
 75→/* On a very short screen (a phone on its side) the filing form needs every pixel,
 76→   so the bar steps aside while the form is open. The form's own header keeps its
 77→   links, and the bar is back on the receipt and on every other page. */
 78→@media (max-height: 520px) {
 79→  body:has(.filing-shell #form-steps:not([hidden])) > .switch-bar {
 80→    display: none;
 81→  }
 82→
 83→  /* W35: the step 3 summary steps aside too, so the fields keep a usable strip
 84→     above Send and Back. */
 85→  .filing-shell .filing-summary {
 86→    display: none;
 87→  }
 88→}
 89→
 90→/* W35: the status page is one screen too, when the screen is tall enough. The
 91→   header and the "Look up a reference number" box stay put; only the "My
 92→   disputes" list scrolls, inside its own region, so scrolling the list never
 93→   hides the lookup box. A lookup result takes the room above the list: the
 94→   list gives up height down to 8rem and the header down to 4.5rem, and only
 95→   then does the result scroll, inside the lookup box. Below 654px the page
 96→   scrolls normally instead: there, on a 320px phone, the fixed header and
 97→   lookup box would press the list to its 8rem floor and then clip the header. */
 98→@media (min-height: 654px) {
 99→  body:has(> .status-shell) {
100→    display: flex;
101→    flex-direction: column;
102→    height: 100vh;
103→    height: 100dvh;
104→    overflow: hidden;
105→  }
106→
107→  body:has(> .status-shell) > .switch-bar {
108→    flex: none;
109→  }
110→
111→  .status-shell {
112→    flex: 1 1 auto;
113→    min-height: 0;
114→    width: 100%;
115→    display: flex;
116→    flex-direction: column;
117→    gap: 0.5rem;
118→    padding: 0.5rem 1.25rem;
119→  }
120→
121→  .status-shell > .party-header {
122→    flex: 0 1 auto;
123→    min-height: 4.5rem;
124→    overflow-y: auto;
125→  }
126→
127→  .status-shell > .party-header h1 {
128→    font-size: 1.25rem;
129→    line-height: 1.2;
130→    margin: 0.25rem 0;
131→  }
132→
133→  .status-shell > .party-header .eyebrow {
134→    font-size: 0.65rem;
135→    padding: 0.1rem 0.5rem;
136→  }
137→
138→  .status-shell > .party-header .demo-note {
139→    margin: 0.25rem 0;
140→    padding: 0.2rem 0.6rem;
141→    font-size: 0.75rem;
142→  }
143→
144→  .status-shell > .party-header .intro {
145→    font-size: 0.85rem;
146→    margin: 0;
147→  }
148→
149→  .status-shell > .party-header > p:last-child {
150→    margin: 0.375rem 0 0;
151→  }
152→
153→  .status-shell > .status-lookup,
154→  .status-shell > .status-list {
155→    margin: 0;
156→    padding: 0.75rem;
157→  }
158→
159→  .status-shell > .status-lookup {
160→    flex: 0 1 auto;
161→    min-height: 0;
162→    display: flex;
163→    flex-direction: column;
164→  }
165→
166→  .status-shell > .status-lookup > :not(#lookup-result) {
167→    flex: none;
168→  }
169→
170→  .status-shell .step h2 {
171→    margin-bottom: 0.5rem;
172→  }
173→
174→  .status-shell > .status-lookup .field {
175→    margin-bottom: 0.5rem;
176→  }
177→
178→  .status-shell > .status-lookup .step-actions {
179→    margin-top: 0.5rem;
180→    padding-top: 0.5rem;
181→  }
182→
183→  .status-shell > .status-lookup > #lookup-result {
184→    flex: 0 1 auto;
185→    min-height: 0;
186→    overflow-y: auto;
187→    overscroll-behavior: contain;
188→  }
189→
190→  .status-shell > .status-lookup > #lookup-result > .step {
191→    margin: 0.5rem 0 0;
192→    padding: 0.75rem;
193→  }
194→
195→  .status-shell > .status-list {
196→    flex: 1 1 0;
197→    min-height: 8rem;
198→    display: flex;
199→    flex-direction: column;
200→  }
201→
202→  .status-shell > .status-list > h2 {
203→    flex: 0 0 auto;
204→  }
205→
206→  .status-shell > .status-list > #account-list {
207→    flex: 1 1 auto;
208→    min-height: 0;
209→    overflow-y: auto;
210→    overscroll-behavior: contain;
211→    padding: 0.75rem;
212→    margin: -0.75rem;
213→  }
214→}
215→

